  ]) {
    for (const m of s.matchAll(re)) add(p, n, t, m[0]);
  }
  for (const m of s.matchAll(/(?:api[_-]?key|token|secret|password|passwd|credential|authorization|auth)[A-Za-z0-9_-]*\s*(?:=|:)\s*["']([^"'\s]{8,})["']/gi)) {
