    add(p, n, "shell-secret-assignment", m[1]);
  }
  for (const m of s.matchAll(/["']([A-Za-z0-9_+\/=.-]{32,})["']/g)) {
    const v = m[1];
    if (/[A-Za-z]/.test(v) && /[0-9]/.test(v) && !/^https?:/.test(v) && !/^[-a-z]+(?:[-.][a-z]+)+$/.test(v)) {
      add(p, n, "long-literal", v);
    }
  }
};
const diff = run(["git", "diff", "--unified=0", "--no-color"]);
let p = "";
let ln = 0;
for (const l of diff.split("\n")) {
  if (l.startsWith("+++ b/")) p = l.slice(6);
  else if (l.startsWith("@@")) {
    const m = l.match(/\+(\d+)/);
    ln = m ? Number(m[1]) : 0;
  } else if (l.startsWith("+") && !l.startsWith("+++")) {
    scan(p, ln, l.slice(1));
    ln++;
  } else if (!l.startsWith("-") && !l.startsWith("\\")) {
    ln++;
  }
}
const us = run(["git", "ls-files", "--others", "--exclude-standard"]).trim().split("\n").filter(Boolean);
for (const p of us) {
  const f = Bun.file(p);
  if ((await f.size) > 5000000) continue;
  const b = new Uint8Array(await f.arrayBuffer());
  if (b.includes(0)) continue;
  const s = d.decode(b);
  s.split("\n").forEach((l, i) => scan(p, i + 1, l));
}
rows.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line);
console.log(JSON.stringify(rows, null, 2));
`;
